import numpy as np

def gen(seed,h,w,cycle=(1,2,3,3,4,4,5,5,6,6),cw=True,start=None):
    # returns (run len >=1...) until wall/occupied; never enter seed
    H,W=h,w
    d=start
    r=[]
    idx=0
    while True:
        run=cycle[idx%len(cycle)]
        dr,dv=[d[0]*k for k in range(run)],[d[1]*k for k in range(run)]
