def diag_lines_through(seed,A_shape):
    h,w=A_shape
    out=np.zeros(h,w,dtype=bool)
    for s in seed:
        r0,c0=s
        for dr,dc in [(1,1),(1,-1),(-1,1),(-1,-1)]:
            for step in [1,-1]:
                rr,cc=r0,c0
                while 0<=rr<h and 0<=cc<w:
                    if rr==r0 and cc==c0: break
                    out[rr,cc]=True
                    rr+=dr*step; cc+=dc*step
    return out
def predict(name,A):
    B=G[name+' output']; h,w=len(A),len(A[0])
    cnt=collections.Counter(x for r in A for x in r)
    b=cnt.most_common(1)[0][0]; fill=sorted(cnt.most_common(),key=lambda x:-x[1])[1][0]
    seed=[(i,j) for i in range(h) for j in range(w) if A[i][j]!=b]
    p=diag_lines_through(seed,(h,w))
    # also fill orthogonal-ish? For demo7, compare
    pred=p.astype(int); 
    diff=((pred&B!=A)&(B!=fill)).sum(); ok=(diff==0); cov=(p.sum(),changed:=sum((B==fill).astype(int)))
