    out=[row[:] for row in inp]; H,HW=H(inp),W(inp); seen={(0,0)}
    dirs=[(-1,0),(0,1),(1,0),(0,-1)]
    seeds=[(r,c) for r in range(H(inp)) for c in range(W(inp)) if inp[r][c]==8]
    for r,c in reversed(sorted(seeds)):
        seen.add((r,c)); out[r][c]=8
        step=1
        rr,cc=r,c
        while True:
            for cyc in range(4):
                for _ in range(step):
                    rr+=dirs[cyc%4][0]; cc+=dirs[cyc%4][1]
                    if 0<=rr<H(inp) and 0<=cc<W(inp) and (rr,cc) not in seen:
                        seen.add((rr,cc)); out[rr][cc]=5
            step+=1
    return out
for i in range(1,9):
    pred=spiral_arms(G[f'Demo pair {i} input'])
    print(i, pred==G[f'Demo pair {i} output'])
